"""Four named source-camera actor construction at the pinned CPU profile.

Callers supply source-grounded static transforms for overview/approach/corner
and a relative driver transform. Real pixel coverage must be audited after run.
"""

from contextlib import contextmanager


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(SIZES):
        raise ValueError("All four named source-camera transforms required")
    sensors = {}
    try:
        for name, (width, height) in SIZES.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("fov", "90")
            blueprint.set_attribute("sensor_tick", "0.05")
            kwargs = {"attach_to": ego} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Original-frame Native source rows for the two C125751 signal cases.

Call record_frame only after all four camera callbacks have joined the current
snapshot. The head-pixel review is a separate post-capture task.
"""
import json
import math

from shapely.geometry import MultiPoint, Polygon


def _number(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("Nonfinite Native " + label)
    return float(value)


def _actor(actor, world_map):
    pose = actor.get_transform()
    vertices = actor.bounding_box.get_world_vertices(pose)
    if len(vertices) < 4:
        raise ValueError("Complete Native body vertices required")
    waypoint = world_map.get_waypoint(actor.get_location(), project_to_road=False)
    if waypoint is None:
        raise ValueError("No Native driving waypoint at original frame")
    velocity = actor.get_velocity()
    body = [[_number(v.x, "body x"), _number(v.y, "body y")] for v in vertices]
    vx, vy, vz = (_number(getattr(velocity, axis), "velocity " + axis) for axis in "xyz")
    return {"actor_id": actor.id,
            "position_xy_m": [_number(pose.location.x, "x"), _number(pose.location.y, "y")],
            "body_vertices_xy_m": body,
            "heading_deg": _number(pose.rotation.yaw, "heading"),
            "velocity_xyz_mps": [vx, vy, vz],
            "speed_mps": math.sqrt(vx*vx + vy*vy + vz*vz),
            "native_road_id": waypoint.road_id, "native_lane_id": waypoint.lane_id,
            "native_junction_id": waypoint.get_junction().id if waypoint.is_junction else None,
            "body_source": "actor.bounding_box.get_world_vertices"}


def _stop_state(actor, polygon):
    angle = math.radians(actor["heading_deg"])
    ahead = (math.cos(angle), math.sin(angle))
    front = max(actor["body_vertices_xy_m"], key=lambda p: p[0]*ahead[0] + p[1]*ahead[1])
    return {"speed_mps": actor["speed_mps"], "front_xy_m": front,
            "body_inside_crossing": MultiPoint(actor["body_vertices_xy_m"]).convex_hull.intersects(polygon),
            "native_road_id": actor["native_road_id"], "native_lane_id": actor["native_lane_id"]}


def _native_state(light):
    state = str(light.get_state()).split(".")[-1]
    if state not in ("Red", "Yellow", "Green", "Off", "Unknown"):
        raise ValueError("Unrecognized Native traffic-light state: " + state)
    return state


def record_frame(frame_map, crossing_stream, signal_stream, stop_stream,
                 snapshot, world_map, ego, other, light, other_light, plan,
                 expected_state, other_expected_state):
    """Append one synchronized original sample after camera frame validation."""
    if (expected_state, other_expected_state) not in (("Green", "Red"), ("Off", "Off")):
        raise ValueError("Exact operative or Off signal pair expected")
    if plan.get("physical_acceptance_claimed") is not False or not plan.get("native_junction_id"):
        raise ValueError("Checked Native junction plan required")
    polygon = Polygon(plan.get("crossing_polygon_xy_m", []))
    if not polygon.is_valid or polygon.area <= 0:
        raise ValueError("Sourced Native crossing polygon required")
    time_s = _number(snapshot.timestamp.elapsed_seconds, "time")
    ego_row, other_row = _actor(ego, world_map), _actor(other, world_map)
    if ego_row["actor_id"] == other_row["actor_id"]:
        raise ValueError("Distinct Native vehicle identities required")
    state, other_state = _native_state(light), _native_state(other_light)
    if state != expected_state or other_state != other_expected_state:
        raise ValueError("Native signal state drift at original frame")
    if type(light.id) is not int or type(other_light.id) is not int or light.id == other_light.id:
        raise ValueError("Two distinct Native signal actor identities required")
    frame = snapshot.frame
    crossing = {"frame": frame, "time_s": time_s, "ego": ego_row, "other": other_row,
                "ego_vertices_m": ego_row["body_vertices_xy_m"]}
    signal = {"frame": frame, "time_s": time_s, "native_signal_id": light.id,
              "state": state, "other_native_signal_id": other_light.id,
              "other_state": other_state}
    stop = {"frame": frame, "time_s": time_s,
            "ego": _stop_state(ego_row, polygon), "other": _stop_state(other_row, polygon)}
    mapped = frame_map.append(frame, time_s)
    for stream, row in ((crossing_stream, crossing), (signal_stream, signal), (stop_stream, stop)):
        stream.write(json.dumps(row, allow_nan=False) + "\n")
    return mapped, crossing, signal, stop


def source_contexts(site, plan, light, other_light):
    """Build sourced geometry/identity contexts, without a head-visibility claim."""
    approaches = plan.get("approaches", {})
    if set(approaches) != {"ego", "other"}:
        raise ValueError("Two checked Native approach plans required")
    for key in ("device_inventory_source", "approach_geometry_source"):
        if not site.get(key):
            raise ValueError("Missing sourced site context: " + key)
    references = site.get("selected_stop_references")
    if not isinstance(references, dict) or set(references) != {"ego", "other"}:
        raise ValueError("Selected source-reviewed stop references required")
    for party, reference in references.items():
        if not isinstance(reference, dict) or reference.get("kind") not in (
                "marked_stop_line", "near_side_crosswalk", "nearest_view_point"):
            raise ValueError("Selected source-reviewed stop reference required: " + party)
        if not reference.get("geometry_source") or not reference.get("reference_review_source"):
            raise ValueError("Stop reference provenance required: " + party)
        segment = reference.get("segment_xy_m")
        if not isinstance(segment, list) or len(segment) != 2 or any(
                not isinstance(p, list) or len(p) != 2 or any(type(v) not in (int, float) or not math.isfinite(v) for v in p)
                for p in segment):
            raise ValueError("Finite stop reference segment required: " + party)
    native_map_name = site.get("native_map_name")
    if (not native_map_name or type(light.id) is not int or type(other_light.id) is not int
            or light.id == other_light.id):
        raise ValueError("Native map and distinct signal identities required")
    ego = approaches["ego"]
    road_geometry = {"intersection_id": plan["native_junction_id"],
        "intersection_polygon_xy_m": plan["crossing_polygon_xy_m"],
        "intersection_polygon_source": plan["crossing_polygon_source"],
        "ego_highway_id": plan["ego_highway_id"],
        "other_highway_id": plan["other_highway_id"],
        "device_inventory_source": site["device_inventory_source"],
        "approach_geometry_source": site["approach_geometry_source"],
        "ego_approach_origin_xy_m": ego["start_xy_m"],
        "other_approach_origin_xy_m": approaches["other"]["start_xy_m"],
        "ego_approach_heading_deg": ego["heading_deg"],
        "other_approach_heading_deg": approaches["other"]["heading_deg"],
        "official_device_status_judgment": "unresolved; requires source review"}
    signal_context = {"intersection_id": plan["native_junction_id"],
        "native_signal_id": light.id, "native_map_id": native_map_name,
        "governed_road_id": ego["road_id"], "governed_lane_id": ego["lane_id"],
        "other_native_signal_id": other_light.id,
        "other_governed_road_id": approaches["other"]["road_id"],
        "other_governed_lane_id": approaches["other"]["lane_id"]}
    stop_context = {"intersection_id": plan["native_junction_id"],
        "selected_references": references}
    return {"road_geometry.json": road_geometry,
            "signal_context.json": signal_context, "stop_context.json": stop_context}

"""Measure two-vehicle intersection entry without deciding legal priority.

The law says "approximately the same time" but supplies no numeric window.
This module reports the observed delta and preserves the roadway/device facts.
"""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon


REQUIRED = ("crossing_history.jsonl", "road_geometry.json", "video_frames.jsonl")


def _source(root, name):
    path = root / name
    if not path.is_file():
        raise ValueError("Missing required source: " + name)
    return path, hashlib.sha256(path.read_bytes()).hexdigest()


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _pair(value, label):
    if not isinstance(value, list) or len(value) != 2 or any(
        not isinstance(v, (int, float)) or isinstance(v, bool) or not math.isfinite(v)
        for v in value
    ):
        raise ValueError("Missing finite " + label)
    return value


def _body(actor):
    vertices = actor.get("body_vertices_xy_m")
    if not isinstance(vertices, list) or len(vertices) < 4:
        raise ValueError("Missing complete participant body")
    return MultiPoint([_pair(v, "body vertex") for v in vertices]).convex_hull


def _right_side(origin, heading_deg, other_origin):
    """Signed lateral projection onto the driver's right-hand axis."""
    theta = math.radians(heading_deg)
    dx, dy = other_origin[0] - origin[0], other_origin[1] - origin[1]
    right_m = dx * math.sin(theta) - dy * math.cos(theta)
    if abs(right_m) < 1.0:
        raise ValueError("Approach side is geometrically ambiguous")
    return right_m


def analyze(root: Path) -> dict:
    root = Path(root)
    paths, hashes = {}, {}
    for name in REQUIRED:
        paths[name], hashes[name] = _source(root, name)
    geometry = json.loads(paths["road_geometry.json"].read_text())
    polygon = geometry.get("intersection_polygon_xy_m")
    if not isinstance(polygon, list) or len(polygon) < 3:
        raise ValueError("Missing identified intersection polygon")
    intersection = Polygon([_pair(v, "intersection vertex") for v in polygon])
    if not intersection.is_valid or intersection.area <= 0:
        raise ValueError("Invalid identified intersection polygon")
    for key in ("intersection_id", "ego_highway_id", "other_highway_id",
                "device_inventory_source", "ego_approach_heading_deg",
                "other_approach_heading_deg", "approach_geometry_source"):
        if key not in geometry or geometry[key] in (None, ""):
            raise ValueError("Missing sourced road context: " + key)
    ego_origin = _pair(geometry.get("ego_approach_origin_xy_m"), "ego approach origin")
    other_origin = _pair(geometry.get("other_approach_origin_xy_m"), "other approach origin")
    for key in ("ego_approach_heading_deg", "other_approach_heading_deg"):
        if type(geometry[key]) not in (int, float) or not math.isfinite(geometry[key]):
            raise ValueError("Finite sourced approach heading required")
    ego_right = _right_side(ego_origin, geometry["ego_approach_heading_deg"], other_origin)
    other_right = _right_side(other_origin, geometry["other_approach_heading_deg"], ego_origin)
    if (ego_right > 0) == (other_right > 0):
        raise ValueError("Approach sides are not reciprocal")
    history, mapping = _rows(paths["crossing_history.jsonl"]), _rows(paths["video_frames.jsonl"])
    if len(history) < 2 or len(mapping) != len(history):
        raise ValueError("Incomplete source/frame map")
    previous = (-1, -math.inf)
    occupancy = {"ego": [], "other": []}
    for i, (row, frame) in enumerate(zip(history, mapping)):
        identity = (row.get("frame"), row.get("time_s"))
        if type(identity[0]) is not int or not isinstance(identity[1], (int, float)) or isinstance(identity[1], bool) or not math.isfinite(identity[1]) or identity[0] <= previous[0] or identity[1] <= previous[1]:
            raise ValueError("Nonmonotone original frame/time")
        previous = identity
        if frame.get("video_frame") != i or frame.get("carla_frame") != identity[0] or abs(frame.get("time_s", -math.inf) - identity[1]) > 1e-4:
            raise ValueError("Original frame/time join failed")
        for participant in ("ego", "other"):
            actor = row.get(participant)
            if not isinstance(actor, dict):
                raise ValueError("Missing participant: " + participant)
            _pair(actor.get("position_xy_m"), participant + " position")
            if _body(actor).intersects(intersection):
                occupancy[participant].append({"frame": identity[0], "time_s": identity[1]})
    first = {who: values[0] if values else None for who, values in occupancy.items()}
    difference = (first["ego"]["time_s"] - first["other"]["time_s"]
                  if all(first.values()) else None)
    heading_difference = ((geometry["other_approach_heading_deg"] -
                           geometry["ego_approach_heading_deg"] + 180) % 360 - 180)
    return {
        "format": "worker-crossing-entry-measurements",
        "sources": hashes,
        "intersection_id": geometry["intersection_id"],
        "highway_ids": [geometry["ego_highway_id"], geometry["other_highway_id"]],
        "device_inventory_source": geometry["device_inventory_source"],
        "first_body_entry": first,
        "ego_minus_other_entry_time_s": difference,
        "approach_heading_difference_deg": heading_difference,
        "approach_geometry_source": geometry["approach_geometry_source"],
        "other_lateral_to_ego_right_m": ego_right,
        "ego_lateral_to_other_right_m": other_right,
        "other_is_to_ego_right": ego_right > 0,
        "ego_is_to_other_right": other_right > 0,
        "geometric_yield_candidate": "ego" if ego_right > 0 else "other",
        "approximately_same_time_judgment": "unresolved; no numeric legal threshold",
        "right_of_way_judgment": "unresolved",
    }

"""Lazy Native construction of an other-from-right median crossing candidate."""
from contextlib import contextmanager
import math

from shapely.geometry import Point, Polygon

from entry_measurements import _right_side


def _xy(transform):
    return float(transform.location.x), float(transform.location.y)


def _waypoint(world_map, transform, label):
    waypoint = world_map.get_waypoint(transform.location, project_to_road=False)
    if waypoint is None:
        raise ValueError("No Native driving waypoint for " + label)
    if getattr(waypoint, "lane_type", None) is not None and "Driving" not in str(waypoint.lane_type):
        raise ValueError("Non-driving Native waypoint for " + label)
    return waypoint


def plan_pair(world_map, site, transforms):
    """Check executable geometry; legal priority remains a saved-source question."""
    required = ("native_map_name", "crossing_id", "ego_highway_id",
                "other_highway_id", "polygon_source", "approach_geometry_source")
    if any(site.get(key) in (None, "") for key in required):
        raise ValueError("Sourced Native crossing and highway identities required")
    if site["ego_highway_id"] == site["other_highway_id"]:
        raise ValueError("Different highway identities required")
    polygon = Polygon(site.get("crossing_polygon_xy_m", []))
    if not polygon.is_valid or polygon.area <= 0:
        raise ValueError("Valid selected crossing polygon required")
    approaches = {}
    for role in ("ego", "other"):
        start = transforms[role + "_approach"]
        entry = transforms[role + "_entry"]
        start_point, entry_point = Point(_xy(start)), Point(_xy(entry))
        if polygon.intersects(start_point) or not polygon.intersects(entry_point):
            raise ValueError(role + " approach/entry misses selected crossing")
        dx, dy = entry_point.x - start_point.x, entry_point.y - start_point.y
        distance = math.hypot(dx, dy)
        yaw = math.radians(float(start.rotation.yaw))
        if distance < 3 or (math.cos(yaw) * dx + math.sin(yaw) * dy) / distance < 0.8:
            raise ValueError(role + " heading does not approach crossing entry")
        start_wp = _waypoint(world_map, start, role + " approach")
        entry_wp = _waypoint(world_map, entry, role + " entry")
        if start_wp.is_junction or not entry_wp.is_junction or entry_wp.get_junction().id != site["crossing_id"]:
            raise ValueError(role + " Native entry is not in selected junction")
        approaches[role] = {
            "start_xy_m": list(_xy(start)), "entry_xy_m": list(_xy(entry)),
            "heading_deg": float(start.rotation.yaw),
            "road_id": start_wp.road_id, "lane_id": start_wp.lane_id,
            "entry_road_id": entry_wp.road_id,
            "entry_lane_id": entry_wp.lane_id}
    if approaches["ego"]["road_id"] == approaches["other"]["road_id"]:
        raise ValueError("Distinct Native approach roads required")
    lateral = _right_side(approaches["ego"]["start_xy_m"],
                          approaches["ego"]["heading_deg"],
                          approaches["other"]["start_xy_m"])
    reciprocal = _right_side(approaches["other"]["start_xy_m"],
                             approaches["other"]["heading_deg"],
                             approaches["ego"]["start_xy_m"])
    if lateral <= 0 or reciprocal >= 0:
        raise ValueError("Other Native approach is not on ego right")
    return {"native_map_name": site["native_map_name"],
            "native_junction_id": site["crossing_id"],
            "ego_highway_id": site["ego_highway_id"],
            "other_highway_id": site["other_highway_id"],
            "crossing_polygon_xy_m": site["crossing_polygon_xy_m"],
            "crossing_polygon_source": site["polygon_source"],
            "approach_geometry_source": site["approach_geometry_source"],
            "other_lateral_to_ego_right_m": lateral,
            "ego_lateral_to_other_right_m": reciprocal,
            "approaches": approaches,
            "physical_acceptance_claimed": False,
            "legal_priority_judgment": "unresolved"}


@contextmanager
def construct_pair(world, site, transforms, other_blueprint):
    world_map = world.get_map()
    if world_map.name != site.get("native_map_name"):
        raise ValueError("Native map differs from reviewed median site")
    plan = plan_pair(world_map, site, transforms)
    other = world.try_spawn_actor(other_blueprint, transforms["other_approach"])
    if other is None:
        raise ValueError("Other-from-right Native spawn failed")
    try:
        yield plan, other
    finally:
        other.destroy()

"""CPU-checkable steering along an authored Native crossing route."""
import math
from shapely.geometry import LineString, Point, Polygon


def validate_route(points, approach, entry, label, crossing_polygon=None):
    if not isinstance(points, list) or len(points) < 3:
        raise ValueError(label + " route needs approach, entry and exit points")
    for point in points:
        if not isinstance(point, list) or len(point) != 2 or any(
                type(v) not in (int, float) or not math.isfinite(v) for v in point):
            raise ValueError(label + " route needs finite XY points")
    if math.dist(points[0], approach[:2]) > 5 or min(
            math.dist(point, entry[:2]) for point in points[1:-1]) > 5:
        raise ValueError(label + " route differs from reviewed approach or entry")
    if any(math.dist(a, b) < 1 for a, b in zip(points, points[1:])):
        raise ValueError(label + " route has duplicate or near-duplicate points")
    if math.dist(points[-1], entry[:2]) < 3:
        raise ValueError(label + " route has no exit beyond crossing entry")
    if crossing_polygon is not None:
        crossing = Polygon(crossing_polygon)
        if not crossing.is_valid or crossing.area <= 0:
            raise ValueError("Valid crossing polygon required for route")
        if crossing.intersects(Point(points[0])):
            raise ValueError(label + " route starts within crossing")
        if crossing.intersects(Point(points[-1])):
            raise ValueError(label + " route ends within crossing")
        if not LineString(points).intersects(crossing) or not any(
                crossing.contains(Point(point)) for point in points[1:-1]):
            raise ValueError(label + " route does not traverse crossing interior")
    return points


def steering_command(x, y, yaw_deg, points, progress=1, lookahead_m=5.0):
    """Return Native steer (+right) and monotone target index for a route."""
    if any(not math.isfinite(v) for v in (x, y, yaw_deg, lookahead_m)) or lookahead_m <= 0:
        raise ValueError("Finite route controller pose and lookahead required")
    if type(progress) is not int or not 1 <= progress < len(points):
        raise ValueError("Valid route target index required")
    while progress < len(points) - 1 and math.dist((x, y), points[progress]) < lookahead_m:
        progress += 1
    target = points[progress]
    distance = math.dist((x, y), target)
    if distance < 0.01:
        return 0.0, progress
    yaw = math.radians(yaw_deg)
    heading = math.atan2(target[1] - y, target[0] - x)
    error = (heading - yaw + math.pi) % (2 * math.pi) - math.pi
    curvature = 2 * math.sin(error) / max(distance, lookahead_m)
    # CARLA VehicleControl.steer is positive for a right turn.
    steer = -math.atan(2.8 * curvature) / math.radians(35)
    return max(-1.0, min(1.0, steer)), progress

"""Native traffic-light selection and reversible state control for C125751.

This controls a real CARLA signal actor; callers must separately retain image
evidence that its vehicular heads are installed and uncovered. A frozen phase is
not, by itself, evidence of an inoperative signal.
"""


def find_governing_signal(world, road_id, lane_id):
    """Choose only a signal whose affected Native waypoint matches the approach."""
    matches = []
    for light in world.get_actors().filter("traffic.traffic_light*"):
        affected = light.get_affected_lane_waypoints()
        if any(wp.road_id == road_id and wp.lane_id == lane_id for wp in affected):
            matches.append(light)
    if len(matches) != 1:
        raise ValueError(f"Expected one governing traffic light, found {len(matches)}")
    return matches[0]


class SignalControl:
    """Apply a requested Native signal state and restore the actor afterward."""

    def __init__(self, world, light, states, target):
        if target not in ("Red", "Green", "Off"):
            raise ValueError("Unsupported target state")
        self.world, self.light, self.states, self.target = world, light, states, target
        self.original = None

    def __enter__(self):
        self.original = self.light.get_state()
        self.light.freeze(True)
        try:
            self.light.set_state(getattr(self.states, self.target))
            self.world.tick()
            if self.light.get_state() != getattr(self.states, self.target):
                raise ValueError("Traffic light state readback failed")
        except Exception:
            self.light.set_state(self.original)
            self.light.freeze(False)
            raise
        return self.light

    def __exit__(self, *_):
        self.light.set_state(self.original)
        self.light.freeze(False)
        self.world.tick()
        if self.light.get_state() != self.original:
            raise ValueError("Traffic light restoration readback failed")


class SignalPairControl:
    """Set two approach-governing lights in one tick and restore both afterward."""

    def __init__(self, world, ego_light, other_light, states, ego_target, other_target):
        if ego_light.id == other_light.id or (ego_target, other_target) not in (
                ("Green", "Red"), ("Off", "Off")):
            raise ValueError("Exact distinct two-approach signal pair required")
        self.world = world
        self.lights = (ego_light, other_light)
        self.states = states
        self.targets = (ego_target, other_target)
        self.originals = None

    def _restore(self):
        for light, original in zip(self.lights, self.originals):
            light.set_state(original)
        for light in self.lights:
            light.freeze(False)
        self.world.tick()
        if any(light.get_state() != original for light, original in zip(self.lights, self.originals)):
            raise ValueError("Traffic-light pair restoration readback failed")

    def __enter__(self):
        self.originals = tuple(light.get_state() for light in self.lights)
        try:
            for light in self.lights:
                light.freeze(True)
            for light, target in zip(self.lights, self.targets):
                light.set_state(getattr(self.states, target))
            self.world.tick()
            if any(light.get_state() != getattr(self.states, target)
                   for light, target in zip(self.lights, self.targets)):
                raise ValueError("Traffic-light pair state readback failed")
        except BaseException:
            self._restore()
            raise
        return self.lights

    def __exit__(self, *_):
        self._restore()

"""Join source-bound signal telemetry to measured intersection entries.

The output describes Native state at each entry. It does not equate an Off
simulation state with the statutory inoperative condition or issue a verdict.
"""

import hashlib
import json
import math
from pathlib import Path


REQUIRED = ("signal_history.jsonl", "video_frames.jsonl", "signal_context.json",
            "head_visibility_review.json", "other_head_visibility_review.json")
VALID_STATES = {"Red", "Yellow", "Green", "Off", "Unknown"}
CAMERAS = {"overview", "approach", "reference_corner", "driver_reference"}


def _read_rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _head_review(root, name, identity, frames):
    review = json.loads((root / name).read_text())
    camera = review.get("camera")
    if camera not in CAMERAS or review.get("native_signal_id") != identity:
        raise ValueError("Reviewed source camera/signal identity missing")
    video = root / (camera + ".mkv")
    if not video.is_file() or hashlib.sha256(video.read_bytes()).hexdigest() != review.get("source_video_sha256"):
        raise ValueError("Head review is not bound to retained source video")
    index = review.get("video_frame")
    if type(index) is not int or not 0 <= index < len(frames) or review.get("carla_frame") != frames[index]["carla_frame"]:
        raise ValueError("Head review frame does not join original source")
    region = review.get("head_region_px")
    if not isinstance(region, list) or len(region) != 4 or any(type(v) is not int or v < 0 for v in region) or region[2] <= region[0] or region[3] <= region[1]:
        raise ValueError("Head review lacks positive pixel region")
    if review.get("installed") is not True or review.get("uncovered") is not True or not review.get("review_basis"):
        raise ValueError("Installed uncovered signal heads lack source review")
    return {"camera": camera, "video_frame": index, "carla_frame": review["carla_frame"],
            "head_region_px": region, "review_basis": review["review_basis"]}, review["source_video_sha256"]


def analyze(root: Path, entry_measurements: dict) -> dict:
    root = Path(root)
    sources = {}
    for name in REQUIRED:
        path = root / name
        if not path.is_file():
            raise ValueError("Missing required signal source: " + name)
        sources[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    context = json.loads((root / "signal_context.json").read_text())
    if context.get("intersection_id") != entry_measurements.get("intersection_id"):
        raise ValueError("Signal and entry intersection identities differ")
    for key in ("native_signal_id", "other_native_signal_id", "native_map_id", "governed_road_id",
                "governed_lane_id", "other_governed_road_id", "other_governed_lane_id"):
        if context.get(key) is None:
            raise ValueError("Missing Native signal provenance: " + key)
    if context["native_signal_id"] == context["other_native_signal_id"]:
        raise ValueError("Distinct governing signals required for two approaches")
    rows = _read_rows(root / "signal_history.jsonl")
    frames = _read_rows(root / "video_frames.jsonl")
    if not rows or len(rows) != len(frames):
        raise ValueError("Incomplete signal/frame history")
    by_frame = {}
    previous = (-1, -math.inf)
    for index, (row, frame) in enumerate(zip(rows, frames)):
        identity = (row.get("frame"), row.get("time_s"))
        if type(identity[0]) is not int or not isinstance(identity[1], (int, float)) or isinstance(identity[1], bool) or not math.isfinite(identity[1]) or identity[0] <= previous[0] or identity[1] <= previous[1]:
            raise ValueError("Nonmonotone signal history")
        previous = identity
        if frame.get("video_frame") != index or frame.get("carla_frame") != identity[0] or frame.get("time_s") != identity[1]:
            raise ValueError("Original signal/frame join failed")
        if (row.get("native_signal_id") != context["native_signal_id"] or row.get("state") not in VALID_STATES
                or row.get("other_native_signal_id") != context["other_native_signal_id"]
                or row.get("other_state") not in VALID_STATES):
            raise ValueError("Signal identity or Native state invalid")
        by_frame[identity[0]] = row
    review, video_sha = _head_review(root, "head_visibility_review.json", context["native_signal_id"], frames)
    other_review, other_video_sha = _head_review(root, "other_head_visibility_review.json",
                                                  context["other_native_signal_id"], frames)
    at_entry = {}
    for party, entry in entry_measurements.get("first_body_entry", {}).items():
        if entry is None:
            at_entry[party] = None
            continue
        row = by_frame.get(entry.get("frame"))
        if row is None or row["time_s"] != entry.get("time_s"):
            raise ValueError("No signal state at measured body entry")
        state_key = "state" if party == "ego" else "other_state"
        id_key = "native_signal_id" if party == "ego" else "other_native_signal_id"
        at_entry[party] = {"frame": row["frame"], "time_s": row["time_s"],
                           "native_state": row[state_key], "native_signal_id": row[id_key]}
    if set(at_entry) != {"ego", "other"}:
        raise ValueError("Both vehicle entries required")
    return {
        "format": "worker-native-signal-at-entry",
        "sources": sources,
        "source_video_sha256": video_sha,
        "other_source_video_sha256": other_video_sha,
        "head_review": review, "other_head_review": other_review,
        "signal_context": context,
        "at_body_entry": at_entry,
        "official_control_judgment": "unresolved; Native actor/state alone does not establish official status",
        "inoperative_judgment": "unresolved; Off is a simulation observation, not a statutory conclusion",
    }

"""Bind the two-signal median-site candidate to exact retained source files.

Hashes establish which planning documents were checked. They do not prove a
physical signal head, official-device status, or statutory crossing identity.
"""
import hashlib
import json
import math
from pathlib import Path


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def source_bindings(site):
    references = site.get("selected_stop_references", {})
    heads = site.get("head_geometry_sources", {})
    if set(references) != {"ego", "other"} or set(heads) != {"ego", "other"}:
        raise ValueError("Two stop references and two head geometry sources required")
    if any(not isinstance(references[role], dict) for role in ("ego", "other")):
        raise ValueError("Two structured stop references required")
    return {
        "polygon": site.get("polygon_source"),
        "approaches": site.get("approach_geometry_source"),
        "device_inventory": site.get("device_inventory_source"),
        "cameras": site.get("camera_plan_source"),
        "ego_stop_geometry": references["ego"].get("geometry_source"),
        "ego_stop_review": references["ego"].get("reference_review_source"),
        "other_stop_geometry": references["other"].get("geometry_source"),
        "other_stop_review": references["other"].get("reference_review_source"),
        "ego_head_geometry": heads["ego"],
        "other_head_geometry": heads["other"],
    }


def _finite_point(value, length):
    return isinstance(value, list) and len(value) == length and all(
        type(x) in (int, float) and math.isfinite(x) for x in value)


def _check_content(kind, document, site):
    content = document.get("content")
    if not isinstance(content, dict):
        raise ValueError("Structured site source content required: " + kind)
    refs = site["selected_stop_references"]
    if kind == "polygon":
        valid = content.get("polygon_xy_m") == site["crossing_polygon_xy_m"]
    elif kind == "approaches":
        valid = content.get("approach_poses") == {role: site[role + "_approach"] for role in ("ego", "other")}
    elif kind == "device_inventory":
        valid = (content.get("governed_road_lanes") == site.get("expected_approach_lanes")
                 and content.get("all_entrances_reviewed") is True)
    elif kind == "cameras":
        valid = content.get("camera_poses") == site["cameras"]
    elif kind.endswith("_stop_geometry"):
        role = kind.split("_")[0]
        valid = content.get("segment_xy_m") == refs[role]["segment_xy_m"]
    elif kind.endswith("_stop_review"):
        role = kind.split("_")[0]
        valid = (content.get("selected_kind") == refs[role]["kind"]
                 and content.get("segment_xy_m") == refs[role]["segment_xy_m"])
    elif kind.endswith("_head_geometry"):
        role = kind.split("_")[0]
        valid = (content.get("governed_road_lane") == site.get("expected_approach_lanes", {}).get(role)
                 and _finite_point(content.get("head_world_location_xyz_m"), 3)
                 and content.get("planned_camera") in site["cameras"])
    else:
        valid = False
    if not valid:
        raise ValueError("Site source content differs from selected geometry: " + kind)


def verify_site_packet(config, base_dir):
    reference = config.get("site_review")
    if not isinstance(reference, dict) or set(reference) != {"path", "sha256"}:
        raise ValueError("Hashed two-signal site review packet required")
    path = Path(reference["path"])
    if not path.is_absolute():
        path = Path(base_dir) / path
    if not path.is_file() or _sha(path) != reference["sha256"]:
        raise ValueError("Two-signal site review packet missing or changed")
    packet = json.loads(path.read_text())
    if packet.get("format") != "worker-c125751-two-signal-site-review" or packet.get("review_status") != "candidate_reviewed":
        raise ValueError("Reviewed two-signal site packet required")
    site = config.get("site")
    if packet.get("site") != site:
        raise ValueError("Site config differs from reviewed packet")
    bindings = source_bindings(site)
    documents = packet.get("source_documents")
    if not isinstance(documents, dict) or set(documents) != set(bindings):
        raise ValueError("Complete two-signal source inventory required")
    verified, diagnostic_only = {}, False
    for kind, path_string in bindings.items():
        source = documents[kind]
        if not isinstance(path_string, str) or not path_string.strip():
            raise ValueError("Missing site source reference: " + kind)
        if not isinstance(source, dict) or set(source) != {"path", "sha256"} or source["path"] != path_string:
            raise ValueError("Hashed site source differs: " + kind)
        source_path = Path(path_string)
        if not source_path.is_absolute():
            source_path = path.parent / source_path
        if not source_path.is_file() or _sha(source_path) != source["sha256"]:
            raise ValueError("Site source missing or changed: " + kind)
        document = json.loads(source_path.read_text())
        if (not isinstance(document, dict) or document.get("format") != "worker-c125751-site-source"
                or document.get("source_kind") != kind
                or document.get("native_map_name") != site.get("native_map_name")
                or document.get("crossing_id") != site.get("crossing_id")
                or not isinstance(document.get("review_basis"), str)
                or not document["review_basis"].strip()
                or type(document.get("diagnostic_only")) is not bool):
            raise ValueError("Site source identity/review invalid: " + kind)
        _check_content(kind, document, site)
        diagnostic_only = diagnostic_only or document["diagnostic_only"]
        verified[kind] = {"path": str(source_path), "sha256": source["sha256"]}
    return {"packet_path": str(path), "packet_sha256": reference["sha256"],
            "source_documents": verified, "diagnostic_only": diagnostic_only,
            "physical_site_verified": False, "official_device_status_verified": False,
            "head_pixel_visibility_verified": False}

"""Saved-source stop and entry-order facts for the subsection-4 comparison.

Zero recorded speed, a position near a selected reference, and another vehicle's
entry order are observations. None alone establishes a statutory stop or yield.
"""
import hashlib
import json
import math
from pathlib import Path

SOURCES = ("stop_context.json", "stop_history.jsonl", "video_frames.jsonl")


def _point(value, label):
    if not isinstance(value, list) or len(value) != 2 or any(
            type(v) not in (int, float) or not math.isfinite(v) for v in value):
        raise ValueError("Missing finite " + label)
    return value


def _distance(point, segment):
    a, b = (_point(v, "stop reference endpoint") for v in segment)
    dx, dy = b[0]-a[0], b[1]-a[1]
    if dx*dx+dy*dy <= 0:
        raise ValueError("Degenerate stop reference segment")
    projection = max(0, min(1, ((point[0]-a[0])*dx+(point[1]-a[1])*dy)/(dx*dx+dy*dy)))
    return math.hypot(point[0]-a[0]-projection*dx, point[1]-a[1]-projection*dy)


def analyze(root: Path, entries: dict) -> dict:
    root = Path(root)
    hashes = {}
    for name in SOURCES:
        path = root / name
        if not path.is_file():
            raise ValueError("Missing required stop source: " + name)
        hashes[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    context = json.loads((root / "stop_context.json").read_text())
    if context.get("intersection_id") != entries.get("intersection_id"):
        raise ValueError("Stop and entry intersection identities differ")
    references = context.get("selected_references")
    if not isinstance(references, dict) or set(references) != {"ego", "other"}:
        raise ValueError("Source-selected stop reference required for each approach")
    for party, reference in references.items():
        if not isinstance(reference, dict) or reference.get("kind") not in (
                "marked_stop_line", "near_side_crosswalk", "nearest_view_point"):
            raise ValueError("Source-selected stop reference required: " + party)
        if not reference.get("geometry_source") or not reference.get("reference_review_source"):
            raise ValueError("Stop reference lacks geometry/review provenance: " + party)
        segment = reference.get("segment_xy_m")
        if not isinstance(segment, list) or len(segment) != 2:
            raise ValueError("Stop reference segment required: " + party)
        _distance(_point(segment[0], "stop reference endpoint"), segment)
    history = [json.loads(s) for s in (root / "stop_history.jsonl").read_text().splitlines() if s.strip()]
    mapping = [json.loads(s) for s in (root / "video_frames.jsonl").read_text().splitlines() if s.strip()]
    if len(history) < 2 or len(history) != len(mapping):
        raise ValueError("Incomplete stop/frame history")
    entry = entries.get("first_body_entry", {})
    if set(entry) != {"ego", "other"} or any(not isinstance(entry[p], dict) for p in ("ego", "other")):
        raise ValueError("Both measured original body entries required")
    first_zero = {"ego": None, "other": None}
    entry_seen = {"ego": False, "other": False}
    ego_at_entry = None
    other_inside_at_ego_entry = None
    last_frame, last_time = -1, -math.inf
    for i, (row, video) in enumerate(zip(history, mapping)):
        frame, time_s = row.get("frame"), row.get("time_s")
        if (type(frame) is not int or type(time_s) not in (int, float) or not math.isfinite(time_s)
                or frame <= last_frame or time_s <= last_time):
            raise ValueError("Nonmonotone original stop frame/time")
        last_frame, last_time = frame, time_s
        if (video.get("video_frame") != i or video.get("carla_frame") != frame
                or video.get("time_s") != time_s):
            raise ValueError("Original stop/video frame join failed")
        for party in ("ego", "other"):
            state = row.get(party)
            if not isinstance(state, dict):
                raise ValueError("Missing original stop state: " + party)
            speed = state.get("speed_mps")
            if type(speed) not in (int, float) or not math.isfinite(speed) or speed < 0:
                raise ValueError("Invalid observed participant speed")
            _point(state.get("front_xy_m"), party + " front position")
            if type(state.get("body_inside_crossing")) is not bool:
                raise ValueError("Missing original body occupancy")
            if frame < entry[party]["frame"] and speed == 0 and first_zero[party] is None:
                first_zero[party] = {"frame": frame, "time_s": time_s,
                                     "front_distance_to_reference_m": _distance(
                                         state["front_xy_m"], references[party]["segment_xy_m"])}
            if frame == entry[party]["frame"]:
                if time_s != entry[party]["time_s"]:
                    raise ValueError(party + " stop/entry timestamp mismatch")
                entry_seen[party] = True
        if frame == entry["ego"]["frame"]:
            ego_at_entry = {"frame": frame, "time_s": time_s,
                            "front_distance_to_reference_m": _distance(
                                row["ego"]["front_xy_m"], references["ego"]["segment_xy_m"])}
            other_inside_at_ego_entry = row["other"]["body_inside_crossing"]
    if ego_at_entry is None or not all(entry_seen.values()):
        raise ValueError("Measured body entry absent from original stop history")
    return {"format": "worker-original-stop-order-measurements", "sources": hashes,
            "intersection_id": context["intersection_id"],
            "selected_references": {party: {"kind": ref["kind"],
                "geometry_source": ref["geometry_source"],
                "reference_review_source": ref["reference_review_source"]}
                for party, ref in references.items()},
            "first_recorded_zero_speed_before_entry": first_zero,
            "ego_at_entry": ego_at_entry,
            "other_first_body_entry_before_ego": entry["other"]["frame"] < entry["ego"]["frame"],
            "other_body_inside_at_ego_entry": other_inside_at_ego_entry,
            "statutory_stop_judgment": "unresolved",
            "statutory_yield_judgment": "unresolved"}

"""Measured-feedback attempt to let the right-hand participant clear."""
import math

from shapely.geometry import MultiPoint, Polygon


def body_in_crossing(actor, crossing_polygon_xy_m):
    vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
    points = [(float(v.x), float(v.y)) for v in vertices]
    if len(points) < 4 or any(not math.isfinite(value) for point in points for value in point):
        raise ValueError("Complete finite Native body required")
    body = MultiPoint(points).convex_hull
    crossing = Polygon(crossing_polygon_xy_m)
    if body.area <= 0 or not crossing.is_valid or crossing.area <= 0:
        raise ValueError("Valid body and crossing required")
    return body.intersects(crossing)


def right_hand_hold(other_inside, other_entered_once):
    if type(other_inside) is not bool or type(other_entered_once) is not bool:
        raise ValueError("Measured Boolean other-body state required")
    seen = other_entered_once or other_inside
    return not seen or other_inside, seen


def near_time_entry_hold(other_inside, other_entered_once):
    """Release only after the right-hand body enters; timing stays measured.

    This is an attempted approach-order controller, not a legal yield decision.
    A later physical review must check interaction safety and actual entry delta.
    """
    if type(other_inside) is not bool or type(other_entered_once) is not bool:
        raise ValueError("Measured Boolean other-body state required")
    seen = other_entered_once or other_inside
    return not seen, seen


def apply_speed_control(carla, actor, target_speed_mps, hold, steer=0.0):
    if type(target_speed_mps) not in (int, float) or not math.isfinite(target_speed_mps) or target_speed_mps <= 0:
        raise ValueError("Positive finite requested speed required")
    velocity = actor.get_velocity()
    speed = math.sqrt(float(velocity.x)**2 + float(velocity.y)**2 + float(velocity.z)**2)
    if not math.isfinite(speed):
        raise ValueError("Finite Native velocity feedback required")
    if type(steer) not in (int, float) or not math.isfinite(steer) or not -1 <= steer <= 1:
        raise ValueError("Finite normalized steering required")
    control = carla.VehicleControl()
    control.steer = steer
    control.throttle = 0.0 if hold else max(0.0, min(0.65, 0.18 + 0.16 * (target_speed_mps - speed)))
    control.brake = 1.0 if hold else min(0.4, max(0.0, 0.3 * (speed - target_speed_mps)))
    actor.apply_control(control)
    return {"measured_speed_mps": speed, "hold": bool(hold),
            "throttle": control.throttle, "brake": control.brake,
            "steer": control.steer}
